try:
    print('>>> x = bytearray()')
    print('>>> y = []')
    print('>>> x ^= y')
    print('>>> x')
    x = bytearray()
    y = []
    x ^= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
